const app=document.querySelector('#app');
const brand='<div class="brand"><b class="mark">⌁</b><div>Med<span>AI</span></div></div>';
const nav=[['dashboard','Visão geral','◫'],['sessao','Sessão de estudo','▤'],['desempenho','Desempenho','▥'],['revisoes','Revisões','↻'],['simulados','Simulados','▧'],['meta','Minha meta','◎'],['assinatura','Assinatura','◇']];
const defaults={logged:false,profile:null,answers:[],reviews:['Hipertensão arterial'],plan:'Essencial',session:null};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('medai-v1')||'{}')}}catch{state={...defaults}}
let selected=null;let messages=[];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('medai-v1',JSON.stringify(state))}catch{toast('O navegador não permitiu salvar o progresso.')}}
function go(route){location.hash=route}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
const button=(label,route,kind='')=>`<a class="btn ${kind}" href="#${route}">${label}</a>`;
const head=(title,sub,action='')=>`<div class="page-head"><div><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;
const areas=[['Clínica Médica',68,'Cardiologia','Hipertensão arterial'],['Cirurgia',74,'Perioperatório','Avaliação pré-operatória'],['Pediatria',81,'Puericultura','Crescimento infantil'],['Ginecologia e Obstetrícia',62,'Pré-natal','Acompanhamento gestacional'],['Medicina Preventiva',85,'Epidemiologia','Rastreamento']];
function shell(content,route){return `<aside>${brand}<div class="nav-caption">SUA PREPARAÇÃO</div><nav>${nav.map(([id,label,icon])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${label}</a>`).join('')}</nav><div class="nav-bottom"><div class="notice small">Um passo por dia.<br>Uma residência no horizonte.</div></div><div class="profile"><div class="avatar">${esc((state.profile?.name||'Ana').slice(0,2).toUpperCase())}</div><div><strong class="small">${esc(state.profile?.name||'Ana')}</strong><br><button class="link" data-action="logout">Sair da demonstração</button></div></div></aside><div class="workspace"><header class="topbar"><span>Seu caminho até a residência</span><div class="top-meta"><span>${esc(state.profile?.exam||'ENARE')} · ${esc(state.profile?.year||2027)}</span><span class="pill">VERSÃO DEMONSTRATIVA</span></div></header><main>${content}<footer class="footer"><span>MedAI · Aprender. Conectar. Evoluir.</span><span>Dados fictícios · Conteúdo educacional, sem uso clínico.</span></footer></main></div>`}
function dashboard(){const total=1248+state.answers.length;return head(`Seu próximo passo, ${esc(state.profile?.name||'Ana')}.`,'Consistência hoje. Mais confiança no dia da prova.',`<span class="pill amber">7 dias de constância</span>`)+`<div class="grid cols"><section class="card session-hero"><span class="pill">SELECIONADA PARA VOCÊ</span><h2>Seu conhecimento merece<br>uma direção.</h2><p class="muted">Hoje, vamos fortalecer sua base em Cardiologia.</p><div class="session-stats"><div><strong>3</strong><span>questões selecionadas</span></div><div><strong>12 min</strong><span>de estudo focado</span></div><div><strong>1</strong><span>tema prioritário</span></div></div>${button(state.session&&!state.session.done?'Continuar minha sessão':'Começar sessão de hoje','sessao')}</section><section class="card"><div class="row"><h2>Sua próxima conquista</h2><span>◎</span></div><p class="muted small">${esc(state.profile?.exam||'ENARE')} · ${esc(state.profile?.year||2027)}</p><div class="row"><div><strong style="font-size:2.8rem;font-weight:600">${daysUntil()}</strong><p class="muted small">dias até sua data-meta</p></div><div class="ring"><div><strong>70%</strong><small>do plano</small></div></div></div><div class="bar"><span style="width:70%"></span></div><p class="muted small" style="margin:15px 0 0">Data estimada por você, sem vínculo com edital.</p></section></div><div class="grid metrics">${[['Questões resolvidas',total.toLocaleString('pt-BR'),'+ '+(48+state.answers.length)+' nesta semana'],['Taxa de acerto',accuracy()+'%','Histórico demonstrativo'],['Tempo de estudo','18h 40','Meta: '+(state.profile?.hours||12)+'h por semana'],['Temas em evolução','24','5 grandes áreas']].map(([l,v,d])=>`<div class="card metric"><span class="muted small">${l}</span><strong>${v}</strong><p class="${l==='Questões resolvidas'?'delta':''}">${d}</p></div>`).join('')}</div><div class="grid cols"><section class="card"><div class="row section-title"><h2 style="margin:0">Seu desempenho por área</h2><a class="link" href="#desempenho">Explorar mapa</a></div>${areas.map(([n,v])=>`<div class="area"><div class="row"><span>${n}</span><strong>${v}%</strong></div><div class="bar"><span style="width:${v}%"></span></div></div>`).join('')}<p class="small muted" style="margin-bottom:0">Domínio estimado · Histórico fictício dos últimos 30 dias</p></section><section class="card"><div class="row"><h2>Foco da semana</h2><span class="pill">${state.profile?.hours||12} h</span></div><div class="week">${['S','T','Q','Q','S','S','D'].map((d,i)=>`<div class="day ${i>3?'future':''}">${d}<i>${i<3?'✓':i===3?'4':'·'}</i></div>`).join('')}</div><div class="task"><div class="task-number">01</div><div class="task-content"><strong class="small">Recuperar conceitos</strong><p>Hipertensão arterial · Prioridade alta</p></div></div><div class="task"><div class="task-number">02</div><div class="task-content"><strong class="small">Revisar no momento certo</strong><p>${state.reviews.length} tema(s) na sua fila</p></div></div><a href="#revisoes" class="link">Ver minhas revisões</a></section></div>`}
function daysUntil(){return Math.max(0,Math.ceil((new Date((state.profile?.date||'2027-10-17')+'T12:00:00')-new Date())/86400000))}
function accuracy(){return Math.round((899+state.answers.filter(a=>a.correct).length)/(1248+state.answers.length)*100)}
function login(){return `<div class="auth"><section class="auth-story">${brand}<div><div class="eyebrow" style="color:#8dded4">PREPARAÇÃO PARA RESIDÊNCIA</div><h1>Conhecimento que<br>se transforma<br>em conquista.</h1><p>Questões, revisão e uma visão clara do que estudar a seguir.</p></div><small>MedAI · Seu próximo capítulo começa aqui.</small></section><section class="auth-form"><div class="form-wrap"><span class="eyebrow">BEM-VINDO AO MEDAI</span><h1 style="margin-top:20px">Vamos estudar?</h1><p class="muted">Explore sua preparação em uma conta demonstrativa.</p><form id="login"><label class="field">Como podemos chamar você?<input name="name" required maxlength="35" placeholder="Seu primeiro nome" autocomplete="given-name"></label><button class="btn full" type="submit">Entrar na demonstração</button></form><div class="notice">Sem senha ou cadastro real. Use um nome fictício. Seu progresso fica apenas neste navegador.</div><p class="muted small">Conteúdo de exemplo para explorar a experiência. Não substitui material de referência ou orientação clínica.</p></div></section></div>`}
function render(){let route=location.hash.slice(1)||'dashboard';if(!state.logged){app.innerHTML=login();return}if(!state.profile){route='onboarding'}const views={dashboard,onboarding:()=>profileForm(true),meta:()=>profileForm(false),sessao:sessionPage,questao:questionPage,correcao:()=>questionPage(true),tutor:tutorPage,desempenho:performance,tema:topicPage,revisoes:reviewsPage,assinatura:plansPage,simulados:mockPage,resultado:resultPage};app.innerHTML=shell(views[route]?views[route]():head('Página não encontrada','Volte à sua preparação.',button('Ir à visão geral','dashboard')),route);window.scrollTo(0,0)}
document.addEventListener('submit',e=>{if(e.target.id==='login'){e.preventDefault();state.logged=true;state.draftName=new FormData(e.target).get('name').trim()||'Estudante';save();render()}});
const questions=[
 {topic:'Hipertensão arterial',title:'Reconhecer o critério diagnóstico',stem:'Em um caso didático, um adulto apresenta pressão arterial de 148/94 mmHg e 146/92 mmHg, aferida adequadamente em dois dias distintos. Segundo o critério geral apresentado pela OMS, qual interpretação é compatível com esses registros?',options:['Os registros são compatíveis com hipertensão arterial.','A ausência de sintomas exclui hipertensão.','Somente a pressão diastólica deve ser considerada.','Uma pressão sistólica abaixo de 160 mmHg exclui hipertensão.'],correct:0,explain:'A OMS descreve como critério geral valores sistólicos ≥ 140 mmHg e/ou diastólicos ≥ 90 mmHg em dois dias distintos. O caso atende a esse critério.',analysis:['As duas aferições ultrapassam os limites descritos.','Hipertensão pode ocorrer sem sintomas.','Os dois componentes da pressão importam.','160 mmHg não é o limite diagnóstico utilizado neste exemplo.'],key:'Compare os valores e a repetição das medidas, sem depender de sintomas.'},
 {topic:'Hipertensão arterial',title:'Interpretar os componentes da pressão',stem:'Em uma questão de fisiologia, o valor sistólico de uma medida de pressão arterial corresponde a qual momento?',options:['Ao relaxamento do coração entre os batimentos.','À contração do coração.','À concentração de oxigênio no sangue.','À frequência cardíaca em repouso.'],correct:1,explain:'A pressão sistólica corresponde à pressão durante a contração cardíaca; a diastólica, ao relaxamento entre os batimentos.',analysis:['Esse momento corresponde à pressão diastólica.','Correto: a contração corresponde à sístole.','Saturação de oxigênio é outra medida.','Frequência e pressão são grandezas diferentes.'],key:'Sístole: contração. Diástole: relaxamento.'},
 {topic:'Hipertensão arterial',title:'Identificar fatores modificáveis',stem:'Qual alternativa apresenta um fator de risco modificável para hipertensão arterial?',options:['Idade.','História familiar.','Consumo excessivo de sal.','Predisposição genética.'],correct:2,explain:'O consumo excessivo de sal é um fator modificável. Idade e predisposição familiar não são modificáveis por hábitos.',analysis:['A idade não é modificável.','A história familiar não pode ser alterada.','A alimentação é passível de mudança.','A predisposição genética não é um hábito modificável.'],key:'Separe características pessoais de exposições e hábitos modificáveis.'}
];
function profileForm(first){const p=state.profile||{name:state.draftName,exam:'ENARE',year:2027,hours:12,specialty:'',date:'2027-10-17'};return head(first?'Uma preparação com a sua direção.':'Minha meta',first?'Personalize seu ponto de partida. Você poderá ajustar tudo depois.':'Seu objetivo orienta o ritmo da preparação.')+`<div class="grid cols"><section class="card"><span class="eyebrow">${first?'CONFIGURAÇÃO INICIAL':'SEU OBJETIVO'}</span><form id="profile"><label class="field">Nome de exibição<input name="name" required maxlength="35" value="${esc(p.name)}"></label><div class="form-row"><label class="field">Prova-alvo<select name="exam">${['ENARE','USP-SP','UNICAMP','SUS-SP','Outra prova'].map(x=>`<option ${p.exam===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Ano da prova<input type="number" name="year" min="2026" max="2040" value="${p.year}" required></label></div><label class="field">Especialidade desejada <span class="muted">Opcional</span><input name="specialty" maxlength="80" value="${esc(p.specialty)}" placeholder="Pesquise uma especialidade" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="specialty-options" aria-describedby="specialty-help"><span id="specialty-options" class="specialty-options" role="listbox" aria-label="Especialidades" hidden></span><span id="specialty-help" class="muted small" style="font-weight:400">Seu objetivo de formação. A oferta de vagas e os pré-requisitos dependem do edital.</span></label><div class="form-row"><label class="field">Horas de estudo por semana<input type="number" name="hours" min="1" max="80" required value="${p.hours}"></label><label class="field">Data-meta estimada<input type="date" name="date" required value="${p.date}"></label></div><p class="muted small">Escolha uma data para sua contagem regressiva. Não representa uma data oficial de prova.</p><button class="btn teal" type="submit">${first?'Criar meu plano de estudo':'Salvar minha meta'}</button></form></section><section class="card" style="align-self:start"><h2>Seu plano começa por aqui</h2><div class="task"><span class="task-number">01</span><div><strong>Pratique</strong><p>Questões para identificar suas lacunas.</p></div></div><div class="task"><span class="task-number">02</span><div><strong>Compreenda</strong><p>Explicações e tutor contextual.</p></div></div><div class="task"><span class="task-number">03</span><div><strong>Retome</strong><p>Erros retornam à fila de revisão.</p></div></div><div class="notice">Neste protótipo, a personalização utiliza regras demonstrativas e um pequeno banco fixo de questões.</div></section></div>`}
function sessionPage(){return head('Seu estudo de hoje','Um ciclo curto: praticar, compreender e revisar.')+`<div class="grid cols"><section class="card"><span class="eyebrow">${esc(state.session?.mode||'SESSÃO PERSONALIZADA')}</span><h2 style="font-size:1.65rem;margin-top:20px">Fortaleça sua base em Cardiologia</h2><p class="muted">Hipertensão arterial é o foco inicial: um tema de menor domínio no seu histórico demonstrativo.</p><div class="notice">Adaptado ao ritmo de ${state.profile.hours} horas semanais. Reserve cerca de 12 minutos para este bloco de 3 questões.</div>${questions.map((q,i)=>`<div class="task"><span class="task-number">0${i+1}</span><div><strong>${q.title}</strong><p>Clínica Médica · Cardiologia · ${i===0?'Revisão':'Fixação'}</p></div></div>`).join('')}<div class="actions"><button class="btn teal" data-action="start">${state.session&&!state.session.done?'Continuar sessão':'Iniciar 3 questões'}</button>${button('Explorar meu mapa','desempenho','secondary')}</div></section><section class="card" style="align-self:start"><h2>Por que este tema?</h2><p class="muted">Domínio inicial de 58% e erros recentes no histórico de exemplo.</p><div class="bar"><span style="width:58%"></span></div><h3 style="margin-top:28px">Ao final, você terá</h3><ul class="checklist"><li>Correção de cada alternativa</li><li>Análise dos seus erros</li><li>Revisões na sua fila</li></ul></section></div>`}
function currentQ(){return questions[state.session?.index||0]}
function currentAnswer(){return state.session?.responses?.[state.session.index]}
function questionPage(correction=false){if(!state.session)return sessionPage();if(state.session.done)return resultPage();const q=currentQ(),a=currentAnswer();if(correction&&a===undefined)correction=false;const answered=a!==undefined;return head(correction?'Entenda o raciocínio':'Uma questão de cada vez',`Questão ${state.session.index+1} de 3 · Clínica Médica · Cardiologia`,button('Pausar e voltar','sessao','secondary'))+`<div class="grid question-layout"><section class="card"><div class="row"><span class="pill">${q.topic}</span><span class="muted small">Autoral · Demonstrativa</span></div><p class="question">${q.stem}</p><div class="answers">${q.options.map((o,i)=>`<button class="answer ${answered?(i===q.correct?'correct':i===a?'wrong':''):(selected===i?'selected':'')}" data-answer="${i}" ${answered?'disabled':''} aria-pressed="${(answered?a:selected)===i}"><span class="letter">${'ABCD'[i]}</span><span>${o}${answered&&i===q.correct?' ✓':''}</span></button>`).join('')}</div>${answered?`<div class="explanation"><span class="pill ${a!==q.correct?'amber':''}">${a===q.correct?'Resposta correta':'Vamos fortalecer este conceito'}</span><h2 style="margin-top:22px">Explicação</h2><p>${q.explain}</p><h3>${a===q.correct?'O que consolidar':'Análise do seu erro'}</h3><p>${q.analysis[a]} ${q.key}</p><details><summary>Análise de todas as alternativas</summary><ul>${q.analysis.map((x,i)=>`<li><strong>${'ABCD'[i]}.</strong> ${x}</li>`).join('')}</ul></details><p class="small muted" style="margin-top:18px">Referência educacional: <a class="link" href="https://www.who.int/news-room/fact-sheets/detail/hypertension" target="_blank" rel="noopener">OMS · Hypertension</a>. Questões autorais, não reproduzidas de prova.</p><div class="actions"><button class="btn teal" data-action="next">${state.session.index===2?'Concluir sessão':'Próxima questão'}</button>${button('Conversar com o tutor','tutor','secondary')}<button class="link" data-action="review">Adicionar à revisão</button></div></div>`:`<div class="actions"><button class="btn teal" data-action="confirm" ${selected===null?'disabled':''}>Confirmar resposta</button><span class="small muted" style="align-self:center">Selecione uma alternativa para continuar.</span></div>`}</section><section class="card" style="align-self:start"><span class="eyebrow">SEU BLOCO DE ESTUDO</span><h2 style="margin-top:20px">Hipertensão arterial</h2><div class="bar"><span style="width:${state.session.index/3*100}%"></span></div><p class="muted small" style="margin-top:12px">${state.session.index} de 3 questões concluídas</p><div class="notice">Leia os dados do enunciado antes de escolher. A correção conecta a resposta ao conceito.</div><p class="muted small">Exemplo simplificado para estudo. Não use este conteúdo para decisões clínicas.</p></section></div>`}
function tutorPage(){if(!state.session)return head('Tutor de estudo','Abra uma questão para conversar sobre o contexto.',button('Ir à sessão','sessao'));const q=currentQ();if(!messages.length)messages=[{role:'bot',text:`Vamos revisar “${q.title}”. Posso explicar o conceito, comentar as alternativas ou resumir o ponto-chave. As respostas são pré-definidas para esta questão.`}];return head('Uma dúvida. Um novo entendimento.','Tutor contextual · Respostas simuladas, sem IA real.',button('Voltar à questão',currentAnswer()!==undefined?'correcao':'questao','secondary'))+`<div class="grid cols"><section class="card"><div class="row"><h2>Tutor MedAI</h2><span class="pill">SIMULADO</span></div><div class="chat" aria-live="polite">${messages.map(m=>`<div class="bubble ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('')}</div><div class="actions">${['Explique o conceito','Analise meu erro','Resuma para revisar'].map(x=>`<button class="btn secondary" data-prompt="${x}">${x}</button>`).join('')}</div><form class="chat-form" id="chat" style="margin-top:22px"><input name="message" required maxlength="300" aria-label="Sua dúvida sobre a questão" placeholder="Escreva sua dúvida sobre esta questão"><button class="btn" type="submit">Enviar</button></form></section><section class="card" style="align-self:start"><span class="eyebrow">QUESTÃO EM CONTEXTO</span><h2 style="margin-top:20px">${q.title}</h2><p class="muted small">${q.stem}</p><button class="link" data-action="review">Guardar para revisar</button></section></div>`}
function chatSend(text){messages.push({role:'user',text});const q=currentQ();const answered=currentAnswer()!==undefined;let response=!answered?'Para preservar sua tentativa, responda à questão primeiro. Observe o conceito central e compare cada alternativa com os dados fornecidos.':/erro|alternativa/i.test(text)?q.analysis[currentAnswer()]+' '+q.key:/resum/i.test(text)?q.key:/conceito|explique|pressão|hipertens/i.test(text)?q.explain+' '+q.key:'Este tutor é uma simulação limitada ao contexto atual. Para esta questão: '+q.key;messages.push({role:'bot',text:response});render();const chat=document.querySelector('.chat');chat.scrollTop=chat.scrollHeight}
function performance(){return head('Veja o que você sabe.','Do panorama geral ao conceito que merece sua atenção.',`<span class="pill">Últimos 30 dias · Exemplo</span>`)+`<div class="grid cols"><section class="card"><div class="row"><h2>Mapa de conhecimento</h2><span class="small muted">Área / especialidade / tema</span></div>${areas.map(([n,v,sub,topic],i)=>`<details ${i===0?'open':''}><summary>${n} <span class="muted small"> · ${v}% de domínio</span></summary><div class="topics"><strong class="small muted">${sub}</strong><a class="topic" href="#tema" data-topic="${i}"><span>${topic}</span><span class="pill ${i===0||i===3?'amber':''}">${i===0?topicMastery():v}% · Ver tema</span></a></div></details>`).join('')}</section><section class="card" style="align-self:start"><h2>Seu aprendizado deixa marcas</h2><p class="muted small">Atividade ilustrativa · 12 semanas</p><div class="heatmap" aria-label="Mapa ilustrativo de atividade de estudo">${Array.from({length:60},()=>'<span></span>').join('')}</div><div class="row small muted"><span>Menos prática</span><span>Mais prática</span></div><div class="notice">As respostas desta demonstração atualizam o domínio de Hipertensão e o total de questões.</div>${button('Revisar ponto prioritário','tema','secondary')}</section></div>`}
function topicMastery(){return Math.min(100,58+state.answers.filter(a=>a.correct).length*4)}
function topicPage(){const i=state.topicIndex||0,[area,value,sub,topic]=areas[i];return head(topic,`${area} / ${sub}`,button('Voltar ao mapa','desempenho','secondary'))+`<div class="grid cols"><section class="card"><div class="row"><div><span class="eyebrow">DOMÍNIO DO TEMA</span><h2 style="font-size:2.8rem;margin:15px 0">${i===0?topicMastery():value}%</h2></div><span class="pill amber">${i===0?'Consolidar fundamentos':'Histórico demonstrativo'}</span></div><div class="bar"><span style="width:${i===0?topicMastery():value}%"></span></div><h2 style="margin-top:30px">Histórico de aprendizagem</h2><div class="task"><span class="task-number">01</span><div><strong>Avaliação inicial</strong><p>Histórico fictício · 10 questões · 50% de acerto</p></div></div><div class="task"><span class="task-number">02</span><div><strong>Revisão guiada</strong><p>Histórico fictício · 6 questões · 67% de acerto</p></div></div>${i===0?state.answers.slice(-5).map(a=>`<div class="task"><span class="task-number">${a.correct?'✓':'↻'}</span><div><strong>${questions[a.q].title}</strong><p>Sua prática neste navegador · ${a.correct?'Acerto':'Revisão recomendada'}</p></div></div>`).join(''):''}</section><section class="card" style="align-self:start"><h2>Próximo passo recomendado</h2><p class="muted">${i===0?'Retome o critério diagnóstico, interprete os componentes da pressão e identifique fatores modificáveis.':'Revise os fundamentos deste tema antes de avançar para questões complexas.'}</p>${i===0?'<button class="btn teal" data-action="directed">Iniciar revisão direcionada</button>':'<div class="notice">O banco executável deste protótipo contém apenas questões de Hipertensão. Outros temas demonstram a navegação do mapa.</div>'+button('Explorar bloco disponível','sessao','secondary')}</section></div>`}
function reviewsPage(){return head('Revisar é fazer permanecer.','Seus erros e conceitos salvos voltam para um novo encontro.')+`<section class="card"><div class="row"><h2>Fila de revisão</h2><span class="pill">${state.reviews.length} tema(s)</span></div>${state.reviews.length?state.reviews.map(t=>`<div class="task"><span class="task-number">↻</span><div class="task-content"><strong>${esc(t)}</strong><p>Disponível agora · 3 questões · Prioridade alta</p></div><button class="btn secondary" data-action="directed">Revisar</button></div>`).join(''):'<div class="empty"><h2>Revisões em dia</h2><p class="muted">Novos erros ou conceitos salvos aparecerão aqui.</p>'+button('Praticar novamente','sessao')+'</div>'}<div class="notice">Regra demonstrativa: erros entram nesta fila. Uma revisão com 3 acertos remove o tema; se houver erros, ele permanece disponível.</div></section>`}
function plansPage(){return head('Mais espaço para evoluir.','Compare os planos ilustrativos. Nenhuma cobrança será realizada.')+`<div class="grid plans">${[['Essencial','Grátis',['Bloco de questões demonstrativo','Mapa de conhecimento','Revisões locais']],['Completo','R$ 89 / mês',['Todos os recursos da demonstração','Tutor contextual simulado','Experiência de plano completo']]].map(([name,price,items])=>`<section class="card ${name==='Completo'?'plan-highlight':''}"><div class="row"><h2>${name}</h2>${state.plan===name?'<span class="pill">SEU PLANO DEMO</span>':''}</div><div class="plan-price">${price}</div><ul class="checklist">${items.map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn ${name==='Essencial'?'secondary':'teal'} full" data-plan="${name}" ${state.plan===name?'disabled':''}>${state.plan===name?'Plano selecionado':'Simular plano '+name}</button></section>`).join('')}</div><div class="notice">Preços fictícios para validar a interface. Nenhum cartão, pagamento ou assinatura real.</div>`}
function mockPage(){return head('Treine o ritmo da prova.','Uma versão reduzida para experimentar o fluxo de simulado.')+`<section class="card" style="max-width:780px"><span class="eyebrow">SIMULADO DEMONSTRATIVO 01</span><h2 style="font-size:1.6rem;margin-top:18px">Fundamentos de Cardiologia</h2><p class="muted">3 questões autorais · Correção ao responder · Sem cronômetro obrigatório</p><div class="notice">Este mini-simulado reutiliza o banco demonstrativo de Hipertensão. Não representa a distribuição de uma prova de residência.</div><button class="btn teal" data-action="mock">Iniciar mini-simulado</button></section>`}
function resultPage(){if(!state.session?.done)return sessionPage();const hits=state.session.responses.filter((a,i)=>a===questions[i].correct).length;return head('Mais um passo construído.','Sua sessão foi concluída e o progresso foi salvo neste navegador.')+`<section class="card" style="max-width:850px"><span class="pill">SESSÃO CONCLUÍDA</span><h2 style="font-size:3rem;margin:22px 0">${hits} de 3 acertos</h2><p class="muted">${hits===3?'Você consolidou os fundamentos deste bloco.':'Os conceitos que precisam de atenção estão na sua fila de revisão.'}</p>${questions.map((q,i)=>`<div class="task"><span class="task-number">${state.session.responses[i]===q.correct?'✓':'↻'}</span><div><strong>${q.title}</strong><p>${state.session.responses[i]===q.correct?'Conceito consolidado':'Retomar na revisão'}</p></div></div>`).join('')}<div class="actions">${button('Ver minhas revisões','revisoes')}${button('Explorar desempenho','desempenho','secondary')}${button('Voltar à visão geral','dashboard','secondary')}</div></section>`}
function start(mode='Sessão personalizada',force=false){if(force||!state.session||state.session.done){state.session={index:0,responses:[],mode,done:false};selected=null;messages=[];save()}go('questao');render()}
document.addEventListener('submit',e=>{if(e.target.id==='profile'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(Number(d.year)!==Number(d.date.slice(0,4))){toast('A data-meta precisa corresponder ao ano da prova.');return}if(!d.name.trim()){toast('Informe um nome de exibição.');return}state.profile={...d,name:d.name.trim(),hours:Number(d.hours),year:Number(d.year)};save();go('dashboard');render();toast('Seu plano de estudo foi salvo.')}if(e.target.id==='chat'){e.preventDefault();const text=new FormData(e.target).get('message').trim();if(text)chatSend(text)}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-answer],[data-prompt],[data-topic],[data-plan]');if(!el)return;if(el.dataset.answer!==undefined){if(currentAnswer()!==undefined)return;selected=Number(el.dataset.answer);render();return}if(el.dataset.prompt){chatSend(el.dataset.prompt);return}if(el.dataset.topic!==undefined){e.preventDefault();state.topicIndex=Number(el.dataset.topic);save();go('tema');render();return}if(el.dataset.plan){state.plan=el.dataset.plan;save();render();toast('Plano '+state.plan+' ativado somente na simulação.');return}switch(el.dataset.action){case'logout':state.logged=false;save();render();break;case'start':start();break;case'directed':start('Revisão direcionada',true);break;case'mock':start('Mini-simulado',true);break;case'confirm':if(selected===null||currentAnswer()!==undefined)return;state.session.responses[state.session.index]=selected;const correct=selected===currentQ().correct;state.answers.push({q:state.session.index,correct,at:new Date().toISOString()});if(!correct&&!state.reviews.includes(currentQ().topic))state.reviews.push(currentQ().topic);save();go('correcao');render();break;case'next':if(currentAnswer()===undefined)return;if(state.session.index===2){state.session.done=true;if(state.session.mode==='Revisão direcionada'&&state.session.responses.every((a,i)=>a===questions[i].correct))state.reviews=state.reviews.filter(t=>t!==currentQ().topic);save();go('resultado')}else{state.session.index++;selected=null;messages=[];save();go('questao')}break;case'review':if(!state.reviews.includes(currentQ().topic))state.reviews.push(currentQ().topic);save();toast('Tema salvo na sua fila de revisão.');break}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_medai',title:'Abrir área do MedAI',description:'Navega para uma área da demonstração sem responder questões ou alterar o progresso.',inputSchema:{type:'object',properties:{page:{type:'string',enum:nav.map(n=>n[0])}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!nav.some(n=>n[0]===input.page))throw Error('Página inválida');if(!state.logged||!state.profile)throw Error('Conclua a entrada e o onboarding primeiro');go(input.page);render();return{page:input.page}}})).catch(()=>{})}catch{}}
window.addEventListener('hashchange',()=>{selected=null;render()});render();



